cat > /private/tmp/100-tricks-runs/d34/without/m4/test/money.test.js << 'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents with exact half rounds to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
});

test('roundCents rounds down', () => {
  assert.equal(roundCents(124.4), 124);
});

test('roundCents rounds up', () => {
  assert.equal(roundCents(124.6), 125);
});

test('roundCents with negative', () => {
  assert.equal(roundCents(-0.5), 0);
  assert.equal(roundCents(-124.5), -124);
});

test('formatEuros basic amount', () => {
  assert.equal(formatEuros(12345), '€123.45');
});

test('formatEuros with thousands separator', () => {
  assert.equal(formatEuros(1234567), '€12,345.67');
});

test('formatEuros with negative', () => {
  assert.equal(formatEuros(-12345), '-€123.45');
});

test('parseEuros basic amount', () => {
  const result = parseEuros('123.45');
  assert.equal(result.ok, true);
  assert.equal(result.value, 12345);
});

test('parseEuros with comma separator', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('parseEuros invalid format returns error', () => {
  const result = parseEuros('abc');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('RATES export contains currencies', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100);
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 8425);
});

test('convert with unknown currency returns error', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with negative amount', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -10850);
});

test('convert rounds correctly', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 109);
});

test('convert zero', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('formatMoney EUR', () => {
  const result = formatMoney(12345, 'EUR');
  assert.equal(result, '€123.45');
});

test('formatMoney USD', () => {
  const result = formatMoney(12345, 'USD');
  assert.equal(result, '$133.84');
});

test('formatMoney GBP', () => {
  const result = formatMoney(12345, 'GBP');
  assert.equal(result, '£104.01');
});

test('formatMoney with thousands separator', () => {
  const result = formatMoney(1234567, 'USD');
  assert.equal(result, '$13,395.15');
});

test('formatMoney with negative amount', () => {
  const result = formatMoney(-12345, 'USD');
  assert.equal(result, '-$133.84');
});

test('formatMoney with unknown currency', () => {
  const result = formatMoney(12345, 'JPY');
  assert.equal(result, 'UNKNOWN');
});

test('formatMoney EUR with thousands', () => {
  const result = formatMoney(1234567, 'EUR');
  assert.equal(result, '€12,345.67');
});

test('convert case insensitive check', () => {
  const result = convert(10000, 'usd');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('formatMoney rounds when converting', () => {
  const result = formatMoney(100, 'USD');
  assert.equal(result, '$1.09');
});

test('convert large amount', () => {
  const result = convert(10000000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850000);
});

test('formatMoney large amount', () => {
  const result = formatMoney(10000000, 'USD');
  assert.equal(result, '$108,500.00');
});
EOF
